const fs = require('fs');
const path = require('path');
const prev = $('Extract Params').item.json;
const mdContent = $input.first().json.data || $input.first().json;
const text = typeof mdContent === 'string' ? mdContent : JSON.stringify(mdContent);

// slugify filename
const ts = new Date().toISOString().slice(0,10);
const safeName = prev.file_name.replace(/[^\w\u4e00-\u9fa5.-]/g,'_').substring(0,50);
const reportPath = `/home/david/xhs-corpus/weekly-reports/${ts}-${safeName}`;
fs.mkdirSync(path.dirname(reportPath), { recursive: true });
fs.writeFileSync(reportPath, text);

return [{ json: { report_path: reportPath, md_content: text, md_length: text.length, ...prev }}];

const fs = require('fs');
const raw = $input.first().json.choices[0].message.content;
const data = JSON.parse(raw);
const prev = $('Save MD to corpus').item.json;

const corpusDir = '/home/david/xhs-corpus';
const hotPath = `${corpusDir}/hot_notes.jsonl`;
const archivePath = `${corpusDir}/hot_notes_archive.jsonl`;

// Load existing hot_notes
let existing = [];
try {
  const content = fs.readFileSync(hotPath, 'utf8');
  existing = content.split('\n').filter(l => l.trim()).map(l => JSON.parse(l));
} catch(e) {}

// Dedupe key: creator + title
const existingKeys = new Set(existing.map(n => `${n.creator}|${n.title}`));

// Archive 8 weeks old
const nowMs = Date.now();
const weekMs = 7 * 24 * 3600 * 1000;
const cutoff = nowMs - 8 * weekMs;
const toArchive = existing.filter(n => new Date(n.added_at).getTime() < cutoff);
const toKeep = existing.filter(n => new Date(n.added_at).getTime() >= cutoff);

if (toArchive.length > 0) {
  fs.appendFileSync(archivePath, toArchive.map(n => JSON.stringify(n)).join('\n') + '\n');
}

// Add new hot_notes (dedupe)
const reportDate = data.report_date || new Date().toISOString().slice(0,10);
const newNotes = [];
for (const n of (data.hot_notes || [])) {
  const key = `${n.creator}|${n.title}`;
  if (existingKeys.has(key)) continue;
  newNotes.push({
    ...n,
    added_at: new Date().toISOString(),
    source_report: prev.report_path.split('/').pop(),
    source_date: reportDate,
    initial_score: 0.5
  });
}

// Write hot_notes.jsonl (kept + new)
const allActive = [...toKeep, ...newNotes];
fs.writeFileSync(hotPath, allActive.map(n => JSON.stringify(n)).join('\n') + (allActive.length ? '\n' : ''));

// Also save creators + categories_meta (for future use)
fs.writeFileSync(`${corpusDir}/creators.jsonl`, (data.creators||[]).map(c => JSON.stringify({...c, updated_at: new Date().toISOString()})).join('\n') + '\n');
fs.writeFileSync(`${corpusDir}/categories_meta.json`, JSON.stringify(data.categories_meta || [], null, 2));
fs.writeFileSync(`${corpusDir}/trends.md`, `# Trends ${reportDate}\n\n${(data.trends || []).map((t,i) => `${i+1}. ${t}`).join('\n')}\n`);

return [{ json: {
  new_hot_notes: newNotes.length,
  archived: toArchive.length,
  active_total: allActive.length,
  creators_updated: (data.creators||[]).length,
  categories: (data.categories_meta||[]).map(c=>c.name),
  report_date: reportDate,
  ...prev
}}];

