const fs = require('fs');
const raw = $input.first().json.choices[0].message.content;
const styles = JSON.parse(raw);

let md = `# Category Style Reference\n\nGenerated: ${new Date().toISOString()}\n\n`;
for (const [cat, s] of Object.entries(styles)) {
  md += `## ${cat}\n\n`;
  md += `- **Tone**: ${s.tone || 'N/A'}\n`;
  md += `- **Emoji Density**: ${s.emoji_density || 'medium'}\n`;
  md += `- **Typical Length**: ${s.typical_length_chars || 300} chars\n`;
  md += `- **Structure**: ${s.structure || 'N/A'}\n`;
  md += `- **Hook Patterns**:\n`;
  for (const h of (s.hook_patterns || [])) md += `  - ${h}\n`;
  md += `\n`;
}
fs.writeFileSync('/home/david/xhs-corpus/category_style.md', md);

return [{ json: { style_categories: Object.keys(styles), style_path: '/home/david/xhs-corpus/category_style.md', ...$('Merge hot_notes + Archive').item.json }}];
